mapper.select:
SELECT DISTINCT assignment.scheduled_date
FROM growth_point_ledger reward
JOIN learn_task_assignment assignment ON assignment.id = reward.source_assignment_id
LEFT JOIN growth_point_ledger correction
  ON correction.correction_of_id = reward.id
 AND correction.change_type = 'CORRECTION'
WHERE reward.student_id = #{studentId}
  AND reward.source_task_id = #{taskId}
  AND reward.source_type = #{sourceType}
  AND reward.change_type = 'TASK_REWARD'
  AND assignment.scheduled_date < #{beforeDate}
  AND correction.id IS NULL
ORDER BY assignment.scheduled_date DESC
LIMIT #{limit}

SELECT id
FROM growth_point_dormancy_notice
WHERE student_id = #{studentId}
  AND activity_baseline_at = #{activityBaselineAt}

