mapper.update:
UPDATE growth_point_dormancy_state
SET last_reminder_created_at = #{now}, version_no = version_no + 1, updated_at = #{now}
WHERE student_id = #{studentId}
  AND version_no = #{expectedVersion}
  AND last_reminder_created_at IS NULL

UPDATE growth_point_dormancy_state
SET last_cleared_at = #{now}, version_no = version_no + 1, updated_at = #{now}
WHERE student_id = #{studentId}
  AND version_no = #{expectedVersion}
  AND last_cleared_at IS NULL

UPDATE growth_point_dormancy_state
SET last_activity_at = #{lastActivityAt}, reminder_due_at = #{reminderDueAt},
    clear_due_at = #{clearDueAt}, last_reminder_created_at = NULL,
    last_cleared_at = NULL, version_no = version_no + 1, updated_at = #{now}
WHERE student_id = #{studentId}
  AND version_no = #{expectedVersion}
  AND last_activity_at < #{lastActivityAt}
